        example:
          'package com.cloudflare.example;\n\nimport com.cloudflare.client.CloudflareClient;\nimport com.cloudflare.client.okhttp.CloudflareOkHttpClient;\nimport com.cloudflare.models.realtimekit.presets.PresetCreateParams;\nimport com.cloudflare.models.realtimekit.presets.PresetCreateResponse;\n\npublic final class Main {\n    private Main() {}\n\n    public static void main(String[] args) {\n        CloudflareClient client = CloudflareOkHttpClient.fromEnv();\n\n        PresetCreateParams params = PresetCreateParams.builder()\n            .accountId("023e105f4ecef8ad9ca31a8372d0c353")\n            .appId("app_id")\n            .config(PresetCreateParams.Config.builder()\n                .maxScreenshareCount(0L)\n                .maxVideoStreams(PresetCreateParams.Config.MaxVideoStreams.builder()\n                    .desktop(0L)\n                    .mobile(0L)\n                    .build())\n                .media(PresetCreateParams.Config.Media.builder()\n                    .screenshare(PresetCreateParams.Config.Media.Screenshare.builder()\n                        .frameRate(0L)\n                        .quality(PresetCreateParams.Config.Media.Screenshare.Quality.HD)\n                        .build())\n                    .video(PresetCreateParams.Config.Media.Video.builder()\n                        .frameRate(30L)\n                        .quality(PresetCreateParams.Config.Media.Video.Quality.HD)\n                        .build())\n                    .build())\n                .viewType(PresetCreateParams.Config.ViewType.GROUP_CALL)\n                .build())\n            .name("name")\n            .ui(PresetCreateParams.Ui.builder()\n                .designTokens(PresetCreateParams.Ui.DesignTokens.builder()\n                    .borderRadius(PresetCreateParams.Ui.DesignTokens.BorderRadius.ROUNDED)\n                    .borderWidth(PresetCreateParams.Ui.DesignTokens.BorderWidth.THIN)\n                    .colors(PresetCreateParams.Ui.DesignTokens.Colors.builder()\n                        .background(PresetCreateParams.Ui.DesignTokens.Colors.Background.builder()\n                            ._600("600")\n                            ._700("700")\n                            ._800("800")\n                            ._900("900")\n                            ._1000("1000")\n                            .build())\n                        .brand(PresetCreateParams.Ui.DesignTokens.Colors.Brand.builder()\n                            ._300("300")\n                            ._400("400")\n                            ._500("500")\n                            ._600("600")\n                            ._700("700")\n                            .build())\n                        .danger("danger")\n                        .success("success")\n                        .text("text")\n                        .textOnBrand("text_on_brand")\n                        .videoBg("video_bg")\n                        .warning("warning")\n                        .build())\n                    .logo("logo")\n                    .spacingBase(0.0)\n                    .theme(PresetCreateParams.Ui.DesignTokens.Theme.DARK)\n                    .build())\n                .build())\n            .build();\n        PresetCreateResponse preset = client.realtimeKit().presets().create(params);\n    }\n}',
